<?php require_once 'config/database.php';require_once 'includes/auth.php';require_once 'includes/ui.php';requireProfile($conn);$uid=(int)$_SESSION['user_id'];$error='';$categories=$conn->query('SELECT id,name FROM categories ORDER BY name');$locations=$conn->query('SELECT id,name FROM locations ORDER BY name');
if($_SERVER['REQUEST_METHOD']==='POST'){$type=$_POST['type']??'';$name=trim($_POST['item_name']??'');$cat=(int)($_POST['category_id']??0);$loc=(int)($_POST['location_id']??0);$date=$_POST['incident_date']??'';$condition=trim($_POST['item_condition']??'');$desc=trim($_POST['description']??'');$imageName='';if(!in_array($type,['LOST','FOUND'])||$name===''||$cat<=0||$loc<=0||$date===''||$desc==='')$error='Lengkapi semua data wajib.';elseif(!empty($_FILES['image']['name'])){$f=$_FILES['image'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>5*1024*1024)$error='Foto maksimal 5 MB.';else{$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime]))$error='Format foto harus JPG, PNG, atau WEBP.';else{$imageName=uniqid('item_',true).'.'.$allowed[$mime];if(!move_uploaded_file($f['tmp_name'],__DIR__.'/uploads/'.$imageName))$error='Foto gagal diunggah.';}}}if($error===''){$st=$conn->prepare('INSERT INTO reports(user_id,category_id,location_id,type,item_name,description,item_condition,incident_date,image,status) VALUES(?,?,?,?,?,?,?,?,?,\'PENDING\')');$st->bind_param('iiissssss',$uid,$cat,$loc,$type,$name,$desc,$condition,$date,$imageName);if($st->execute()){header('Location: laporan.php?success=1');exit;}else{$error='Laporan gagal disimpan: '.$conn->error;}$st->close();}}
$titleForTop='Buat Laporan';renderHead('Buat Laporan');renderUserNav('laporan');?><div class="content animate-in"><div class="section-head"><div><h1 class="hero-title">Buat Laporan</h1><p class="muted">Laporkan barang hilang atau barang yang kamu temukan.</p></div></div><?php if($error): ?><div class="notice notice-error"><?= e($error) ?></div><?php endif; ?><div class="card form-card"><form method="post" enctype="multipart/form-data"><div class="form-group"><label>Jenis Laporan</label><div class="type-grid"><div class="type-option"><input id="lost" type="radio" name="type" value="LOST" <?= ($_POST['type']??'')==='LOST'?'checked':'' ?> required><label class="type-label" for="lost">🔴 <b>Barang Hilang</b><br><span class="muted">Saya kehilangan barang.</span></label></div><div class="type-option"><input id="found" type="radio" name="type" value="FOUND" <?= ($_POST['type']??'')==='FOUND'?'checked':'' ?>><label class="type-label" for="found">🟢 <b>Barang Ditemukan</b><br><span class="muted">Saya menemukan barang.</span></label></div></div></div><div class="form-group"><label>Nama Barang</label><input class="form-control" name="item_name" maxlength="150" value="<?= e($_POST['item_name']??'') ?>" placeholder="Contoh: Dompet hitam" required></div><div class="form-row"><div class="form-group"><label>Kategori</label><select class="form-select" name="category_id" required><option value="">Pilih kategori</option><?php while($c=$categories->fetch_assoc()): ?><option value="<?= $c['id'] ?>" <?= (($_POST['category_id']??'')==$c['id'])?'selected':'' ?>><?= e($c['name']) ?></option><?php endwhile; ?></select></div><div class="form-group"><label>Lokasi</label><select class="form-select" name="location_id" required><option value="">Pilih lokasi</option><?php while($l=$locations->fetch_assoc()): ?><option value="<?= $l['id'] ?>" <?= (($_POST['location_id']??'')==$l['id'])?'selected':'' ?>><?= e($l['name']) ?></option><?php endwhile; ?></select></div></div><div class="form-row"><div class="form-group"><label>Tanggal Kejadian</label><input class="form-control" type="date" name="incident_date" value="<?= e($_POST['incident_date']??'') ?>" required></div><div class="form-group"><label>Kondisi Barang</label><input class="form-control" name="item_condition" value="<?= e($_POST['item_condition']??'') ?>" placeholder="Contoh: Ada goresan kecil"></div></div><div class="form-group"><label>Deskripsi & Ciri Khusus</label><textarea rows="6" name="description" required placeholder="Warna, merek, ciri khusus, isi barang, dan detail yang membantu pencocokan..."><?= e($_POST['description']??'') ?></textarea></div><div class="form-group"><label>Foto Barang</label><input class="form-control" type="file" name="image" accept="image/jpeg,image/png,image/webp"><small class="muted">JPG, PNG, WEBP — maksimal 5 MB.</small></div><div class="actions"><a class="btn btn-light" href="dashboard.php">Batal</a><button class="btn btn-primary" type="submit">Kirim Laporan</button></div></form></div></div><?php renderFooter(); ?>
